python3 - <<'PY'
from pathlib import Path
p = Path('src/climate/output/OutputTypes.h')
s = p.read_text()
needle = 'enum class TransportStatus : std::uint8_t { NotAttempted = 0U, Completed, Failed };\n'
replacement = needle + '\nenum class PhysicalOutputState : std::uint8_t { Unknown = 0U, Off, On };\n'
assert needle in s and 'PhysicalOutputState' not in s
p.write_text(s.replace(needle, replacement, 1))
contracts = '''#pragma once

#include "climate/output/OutputIntents.h"

#include <array>
#include <cstddef>
#include <cstdint>

namespace growbox::app::output {

struct OutputCommand {
  OutputEndpointId endpoint = kInvalidOutputEndpoint;
  BinaryOutputState state = BinaryOutputState::Off;
  OutputSource source = OutputSource::None;
  OutputReason reason = OutputReason::None;
  std::uint64_t sequence = 0U;
  std::uint64_t due_ms = 0U;
};

constexpr bool outputCommandValid(const OutputCommand& command) noexcept {
  return isValidOutputEndpoint(command.endpoint);
}

struct OutputPlan {
  std::array<OutputCommand, kOutputEndpointCapacity> steps{};
  std::uint8_t size = 0U;
};

constexpr bool appendOutputCommand(OutputPlan& plan, const OutputCommand& command) noexcept {
  if (!outputCommandValid(command) || plan.size >= kOutputEndpointCapacity) {
    return false;
  }
  plan.steps[plan.size] = command;
  ++plan.size;
  return true;
}

struct TxResult {
  TransportStatus status = TransportStatus::NotAttempted;
  TransportError error = TransportError::None;
};

struct ExecutionStepResult {
  OutputCommand command{};
  TxResult transport{};
  PhysicalOutputState physical = PhysicalOutputState::Unknown;
};

struct ExecutionReport {
  std::array<ExecutionStepResult, kOutputEndpointCapacity> steps{};
  std::uint8_t size = 0U;
};

constexpr bool appendExecutionResult(ExecutionReport& report,
                                     const ExecutionStepResult& result) noexcept {
  if (report.size >= kOutputEndpointCapacity) {
    return false;
  }
  report.steps[report.size] = result;
  ++report.size;
  return true;
}

struct ExecutedControlProjection {
  std::array<EndpointIntent, kOutputEndpointCapacity> endpoints{};
};

} // namespace growbox::app::output
'''
Path('src/climate/output/OutputExecution.h').write_text(contracts)
test = '''#include "climate/output/OutputExecution.h"

#include <cassert>
#include <type_traits>

using namespace growbox::app::output;

static_assert(std::is_trivially_copyable_v<OutputCommand>);
static_assert(std::is_trivially_copyable_v<OutputPlan>);
static_assert(std::is_trivially_copyable_v<TxResult>);
static_assert(std::is_trivially_copyable_v<ExecutionStepResult>);
static_assert(std::is_trivially_copyable_v<ExecutionReport>);
static_assert(std::is_trivially_copyable_v<ExecutedControlProjection>);

int main() {
  OutputPlan plan{};
  ExecutionReport report{};
  assert(plan.size == 0U);
  assert(report.size == 0U);

  OutputCommand first{};
  first.endpoint = 2U;
  first.state = BinaryOutputState::On;
  first.sequence = 10U;
  OutputCommand second{};
  second.endpoint = 1U;
  second.state = BinaryOutputState::Off;
  second.sequence = 11U;
  assert(appendOutputCommand(plan, first));
  assert(appendOutputCommand(plan, second));
  assert(plan.size == 2U);
  assert(plan.steps[0].endpoint == 2U);
  assert(plan.steps[1].endpoint == 1U);

  OutputCommand third{}; third.endpoint = 3U;
  assert(appendOutputCommand(plan, third));
  OutputCommand overflow{}; overflow.endpoint = 4U;
  assert(!appendOutputCommand(plan, overflow));
  assert(plan.size == kOutputEndpointCapacity);
  OutputCommand invalid{};
  OutputPlan invalid_plan{};
  assert(!appendOutputCommand(invalid_plan, invalid));
  assert(invalid_plan.size == 0U);

  ExecutionStepResult failed{};
  failed.command = first;
  failed.transport = {TransportStatus::Failed, TransportError::IoFailure};
  failed.physical = PhysicalOutputState::Unknown;
  assert(appendExecutionResult(report, failed));
  assert(report.steps[0].transport.status == TransportStatus::Failed);
  assert(report.steps[0].physical == PhysicalOutputState::Unknown);

  ExecutionStepResult completed{};
  completed.command = second;
  completed.transport = {TransportStatus::Completed, TransportError::None};
  completed.physical = PhysicalOutputState::Unknown;
  assert(appendExecutionResult(report, completed));
  assert(report.size == 2U);
  assert(report.steps[0].transport.status == TransportStatus::Failed);
  assert(report.steps[1].transport.status == TransportStatus::Completed);
  return 0;
}
'''
Path('test/test_output_execution_contracts').mkdir(parents=True, exist_ok=True)
Path('test/test_output_execution_contracts/test_main.cpp').write_text(test)
p = Path('test/host/CMakeLists.txt')
