target_compile_options(output_execution_contract_tests PRIVATE -Wall -Wextra -Wpedantic)

'''
assert anchor in s and 'output_execution_contract_tests' not in s
s = s.replace(anchor, block + anchor, 1)
test_anchor = 'add_test(NAME output_intents_tests COMMAND output_intents_tests)'
s = s.replace(test_anchor, 'add_test(NAME output_execution_contract_tests COMMAND output_execution_contract_tests)\n' + test_anchor, 1)
p.write_text(s)
